import{_ as t}from"./chunks/Audio.COine8Wh.js";import{_ as s}from"./chunks/Tags.BJ536pW3.js";import{c as a,o as n,j as i,G as r,ae as o,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const v=JSON.parse('{"title":"Trafficking Survivors Relief Act","description":"","frontmatter":{"legisId":"2026-01-23-trafficking-survivors-relief-act","title":"Trafficking Survivors Relief Act","displayTitle":"Trafficking Survivors Relief Act","lawNumber":"119-73","billNumber":"H.R. 4323","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ73.xml","publishDate":"2026-01-23T00:00:00-05:00","industries":["law-enforcement","government-operations"],"agencies":[],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Trafficking Survivors Relief Act\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2026-01-23-trafficking-survivors-relief-act\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Trafficking Survivors Relief Act\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2026-01-23-trafficking-survivors-relief-act\\",\\"datePublished\\":\\"2026-01-23T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2026-01-23-trafficking-survivors-relief-act\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2026-01-23-trafficking-survivors-relief-act.md","filePath":"congress-bills/2026-01-23-trafficking-survivors-relief-act.md","lastUpdated":1788887623000}'),c={name:"congress-bills/2026-01-23-trafficking-survivors-relief-act.md"},m=Object.assign(c,{setup(f){return(d,e)=>(n(),a("div",null,[e[0]||(e[0]=i("h1",{id:"trafficking-survivors-relief-act",tabindex:"-1"},[l("Trafficking Survivors Relief Act "),i("a",{class:"header-anchor",href:"#trafficking-survivors-relief-act","aria-label":'Permalink to "Trafficking Survivors Relief Act"'},"​")],-1)),r(t),r(s,{list:"/congress-bills"}),e[1]||(e[1]=o('<p>Signed into law on Friday, January 23, 2026. Public Law 119-73, H.R. 4323.</p><p><strong>Headline:</strong> Human trafficking survivors can seek to clear certain federal records and reduce sentences tied directly to their trafficking.</p><p><strong>Why it matters:</strong> The law gives survivors a path to lessen the lasting legal consequences of offenses they were compelled to commit while being trafficked.</p><p><strong>What the law does:</strong></p><ul><li>Allows courts to vacate qualifying nonviolent federal convictions.</li><li>Permits expungement of qualifying arrest records, including limited violent offenses that did not involve a child victim.</li><li>Authorizes sentence reductions for qualifying offenses resulting directly from trafficking.</li><li>Creates a trafficking-based duress defense.</li><li>Seals case records, waives filing and processing fees, and allows appeals.</li><li>Permits eligible grants to fund post-conviction representation and requires federal implementation reports.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Human trafficking survivors with qualifying federal convictions, arrest records, or prison sentences.</li><li>Federal courts handling relief requests and appeals.</li><li>Legal service providers eligible for grant funding.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>A survivor may clear qualifying convictions or arrest records and generally regain their pre-case status under federal law.</li><li>A survivor may seek a shorter sentence without paying filing or processing fees, though fines and restitution may remain.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="trafficking-survivors-relief-act-1" tabindex="-1">Trafficking Survivors Relief Act <a class="header-anchor" href="#trafficking-survivors-relief-act-1" aria-label="Permalink to &quot;Trafficking Survivors Relief Act&quot;">​</a></h3><p>The Trafficking Survivors Relief Act allows human trafficking survivors to ask federal courts to clear certain convictions and arrest records when the conduct resulted directly from trafficking. It also permits sentence reductions, creates a trafficking-based duress defense, protects applicants’ confidentiality, and requires reporting on implementation.</p><p><strong>Key takeaways:</strong></p><ul><li>Survivors may seek to vacate federal convictions for nonviolent offenses committed as a direct result of being trafficked.</li><li>Survivors may seek expungement of arrest records for nonviolent offenses and, in limited circumstances, violent offenses that did not involve a child victim.</li><li>Courts may reduce prison sentences for qualifying nonviolent or violent offenses committed as a direct result of trafficking.</li><li>Successful relief generally restores the survivor’s status under federal law to what it was before the arrest or prosecution, but courts are not required to remove fines or restitution orders.</li><li>Motions and related records must be sealed, applicants cannot be charged filing or processing fees, and court decisions may be appealed.</li><li>The Act creates a trafficking-based duress defense, permits eligible grants to fund post-conviction representation, and requires federal reports on motions, outcomes, training, and access to relief.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ73.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ73.xml</a></p>',15))]))}});export{v as __pageData,m as default};
